// Writes CHANGELOG.md into lib/changelog/changelog.generated.ts so /whats-new
// needs no filesystem read at request time. A Cloudflare Worker has no
// filesystem (node:fs under nodejs_compat is an empty virtual one), see
// decision 0018 and openspec/changes/move-to-cloudflare/design.md (D1).
//
// The output is gitignored and regenerated by `build`, `dev`, `typecheck` and
// vitest.config.ts, so a clean checkout passes all of them. The file is only
// rewritten when its content changes, so `next dev` does not reload for nothing.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const OUTPUT = path.join(root, "lib/changelog/changelog.generated.ts");

export function renderChangelogModule(markdown) {
  return (
    "// Generated by scripts/generate-changelog-module.mjs from CHANGELOG.md. Do not edit.\n" +
    `export const CHANGELOG_MD: string = ${JSON.stringify(markdown)};\n`
  );
}

export function generateChangelogModule() {
  let markdown = "";
  try {
    markdown = fs.readFileSync(path.join(root, "CHANGELOG.md"), "utf8");
  } catch {
    // An absent CHANGELOG.md renders the page's empty state, as before.
  }
  const next = renderChangelogModule(markdown);
  const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, "utf8") : null;
  if (current !== next) fs.writeFileSync(OUTPUT, next);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  generateChangelogModule();
}
